def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "play_polite_audio": And([
            self.setting_is_post_office,
            self.humans_present,
            Not(self.robot_understands_social_context)
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
